import{_ as d,o as t,c as o,a2 as i}from"./chunks/framework.DqYch1Cg.js";const m=JSON.parse('{"title":"旧学习笔记迁移记录","description":"","frontmatter":{},"headers":[],"relativePath":"学习资源/笔记迁移记录.md","filePath":"学习资源/笔记迁移记录.md","lastUpdated":1794211306000}'),a={name:"学习资源/笔记迁移记录.md"};function c(r,e,l,n,h,s){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="旧学习笔记迁移记录" tabindex="-1">旧学习笔记迁移记录 <a class="header-anchor" href="#旧学习笔记迁移记录" aria-label="Permalink to &quot;旧学习笔记迁移记录&quot;">​</a></h1><p>这次整理以 <code>Fridolph/Fridolph</code> 的 <strong>dev</strong> 分支 <code>c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7</code> 为输入，目标是把能够继续验证的知识放进 Web 开发学习宝典。源仓库保持原样，以下记录每一类素材的去向和取舍。</p><blockquote><p>迁移原则：重写优先于整篇复制；先纠正过期或容易误导的结论；代码保留可运行边界；个人服务器地址、账户、密码、密钥和内部网络信息不进入本站；课件、图片和第三方整篇文章保留在源仓库并只记录出处。</p></blockquote><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>源目录</th><th style="text-align:right;">文件数</th><th>当前归位</th><th>处理方式</th></tr></thead><tbody><tr><td><code>部署相关知识</code></td><td style="text-align:right;">31</td><td><a href="/FE-prepare-interview/概念与原理/20deploy/intro">开发与部署</a></td><td>31 个文件逐组盘点；Linux / SSH、Nginx、PM2、Docker 主题重写归并；私人服务器资料、首页效果素材和旧 MongoDB 安装说明留在源仓库</td></tr><tr><td><code>工程构建相关/git学习</code></td><td style="text-align:right;">3</td><td><a href="/FE-prepare-interview/概念与原理/20deploy/s_deploy_2-git">Git 工作区与团队协作</a></td><td>3 个 Markdown 合并，补充现代 switch / restore、共享分支和 squash 历史边界</td></tr><tr><td><code>算法相关</code></td><td style="text-align:right;">31</td><td><a href="/FE-prepare-interview/编码与实践/03algo/intro">算法实践</a>；<a href="/FE-prepare-interview/编码与实践/02js/c_js_3-small_utilities/c_js_3-small_utilities">JS 小工具</a></td><td>排序重复实现折叠进现有排序文章；二分、随机、两数之和、回文、字符统计、数列等重写为4组源码并测试；未完成 / 重复 / 旧深克隆只保留主题和链接</td></tr><tr><td><code>性能优化相关</code></td><td style="text-align:right;">42</td><td><a href="/FE-prepare-interview/概念与原理/06opt/intro">性能主题</a></td><td>资源、图片、脚本、渲染、存储和 Service Worker 合并为3篇现代实践；PPTX、示例照片、旧 demo 和通用 utils 不复制；原有文章继续保留</td></tr><tr><td><code>正则表达式</code></td><td style="text-align:right;">12</td><td><a href="/FE-prepare-interview/概念与原理/02js/s_js_6-regexp">JavaScript 正则表达式</a></td><td>语法、分组、捕获、常用格式和读书摘记合并；index.html、test.js 等练习壳不迁；补充 Unicode、lastIndex、ReDoS 与校验边界</td></tr><tr><td><code>HTTP</code></td><td style="text-align:right;">28</td><td><a href="/FE-prepare-interview/概念与原理/04http/intro">HTTP 与网络</a>、<a href="/FE-prepare-interview/概念与原理/20deploy/s_deploy_3-nginx">开发与部署/Nginx</a></td><td>协议、CORS、Cookie / Session / Token、协商、重定向和缓存归并；demo、PDF、图片和整篇 MDN 不复制；Nginx 通用配置转到开发与部署</td></tr><tr><td><code>interviewMap</code></td><td style="text-align:right;">27</td><td><a href="/FE-prepare-interview/学习自测/index">学习自测</a></td><td>JS、浏览器、安全、性能和 MVVM 归并为6篇自测；原有主题保留，新增回答强调验证和边界；HTML 测试壳不迁</td></tr></tbody></table><p>合计盘点 <strong>174 个文件</strong>。表中“合并”表示内容已吸收并重写，不表示源文件逐字搬运。</p><h2 id="分组处理明细" tabindex="-1">分组处理明细 <a class="header-anchor" href="#分组处理明细" aria-label="Permalink to &quot;分组处理明细&quot;">​</a></h2><h3 id="部署相关知识-31" tabindex="-1">部署相关知识（31） <a class="header-anchor" href="#部署相关知识-31" aria-label="Permalink to &quot;部署相关知识（31）&quot;">​</a></h3><ul><li><code>linux-centos/</code>：10 个文件。硬件、文件、用户、SSH、服务和 Nginx 的有效知识归入 Linux / SSH 与 Nginx 文章；CentOS 7 已停止常规维护，旧 yum / service / chkconfig 操作改成发行版和 systemd 视角；图片目录结构图不复制。</li><li><code>ubuntu相关/</code>：9 个文件。SSH 密钥、端口和防火墙的原则合入 Linux / SSH；Node 和 Nginx 的测试文件不复制；旧 MongoDB 安装说明含过时版本和不安全配置，留在源仓库不作为指引。</li><li><code>nginx/</code>：2 个文件。配置和外网说明合入 Nginx 文章，私有 IP、域名和账号信息不公开。</li><li><code>pm2/</code>：1 个文件。进程守护、ecosystem、信号和退出清理合入 Node 进程文章。</li><li><code>readme.md</code>、<code>txy.md</code>：2 个文件。历史部署背景与私人环境资料保留源仓库；可复用原则改写进发布文章。</li><li><code>首页/</code>：7 个文件。静态首页效果、图片和构建产物不是本项目学习主线，不复制。</li></ul><h3 id="工程构建相关-git学习-3" tabindex="-1">工程构建相关/git学习（3） <a class="header-anchor" href="#工程构建相关-git学习-3" aria-label="Permalink to &quot;工程构建相关/git学习（3）&quot;">​</a></h3><p><code>00简易入门.md</code>、<code>01基本概念.md</code>、<code>02常用命令.md</code> 全部进入 Git 文章；旧命令说明改成 <code>switch</code> / <code>restore</code>、fetch / pull、revert / reset 和共享分支协作语境。</p><h3 id="算法相关-31" tabindex="-1">算法相关（31） <a class="header-anchor" href="#算法相关-31" aria-label="Permalink to &quot;算法相关（31）&quot;">​</a></h3><ul><li><code>十大经典算法/</code> 5 个：排序基础已存在，按重复内容折叠；不重复复制四套排序实现。</li><li><code>算法与数据结构学习/</code> 6 个：随机数组、选择排序等重复素材归并到随机和排序主题；空的 <code>typename</code> 工具不迁。</li><li><code>练习-未整理/</code> 5 个：两数之和、回文、阶乘、最长单词、随机数分别进入数组 / 字符串、数列和随机文章。</li><li><code>解法/</code> 4 个：二分查找与插入位置重写；选择排序归入现有排序；数组乱序保留算法思想和出处。</li><li><code>面试相关/</code> 9 个：模板、trim、对象最大值、去重、扁平化、斐波那契、深克隆、数组和 DOM 计数重写为 JS 小工具或算法说明；深克隆链接现有文章。</li><li><code>测试/</code> 2 个：字符统计的未完成版本和正则限制版本不原样复制，改为 Unicode 码点规则的 <code>Map</code> 实现。</li></ul><h3 id="性能优化相关-42" tabindex="-1">性能优化相关（42） <a class="header-anchor" href="#性能优化相关-42" aria-label="Permalink to &quot;性能优化相关（42）&quot;">​</a></h3><ul><li><code>1资源的压缩与合并/</code> 2、<code>2图片相关优化/</code> 1、<code>3样式脚本的装载与执行/</code> 1：进入资源加载文章，补充现代 HTTP/2/3、格式回退、脚本执行语义。</li><li><code>4懒加载与预加载/</code> 7、<code>5回流与重绘/</code> 5：有效原理进入资源 / 渲染文章；4 张图片、HTML 演示和旧脚本不复制。</li><li><code>6浏览器存储/</code> 7、<code>7缓存优化/</code> 2：进入浏览器存储与离线缓存；旧 Service Worker 的时间戳缓存、删除全部同源缓存和未处理 miss 已改写。</li><li><code>基础优化/</code> 3、<code>高效前端/</code> 2、<code>优化专题目录.md</code> 1：指标、测量和优化方法进入性能测量；其中整篇第三方摘记只保留来源，不整篇转载。</li><li><code>性能优化专题/</code> 6 个 PPTX：课件文件留在源仓库，不放入站点构建。</li><li><code>utils/</code> 5 个：与当前知识主线无直接关系，留在源仓库。</li></ul><h3 id="正则表达式-12" tabindex="-1">正则表达式（12） <a class="header-anchor" href="#正则表达式-12" aria-label="Permalink to &quot;正则表达式（12）&quot;">​</a></h3><p><code>01基础.md</code>、<code>02分组.md</code>、<code>03常用正则/</code> 5 个、<code>04捕获.md</code>、<code>忍者正则.md</code>、<code>笔记.md</code> 共 10 个 Markdown 合并；<code>index.html</code> 和 <code>test.js</code> 2 个练习壳不迁。日期、数字、邮箱、姓名和电话正则均改为“格式检查而非业务事实验证”的表述。</p><h3 id="http-28" tabindex="-1">HTTP（28） <a class="header-anchor" href="#http-28" aria-label="Permalink to &quot;HTTP（28）&quot;">​</a></h3><ul><li><code>01协议基础/</code> 9 个：协议分层、历史、TCP / TLS 与 HTTP 区分、URI、报文归入协议文章；图片不复制。</li><li><code>02特性总览/</code> 2、<code>03Cookie/</code> 3、<code>04数据协商/</code> 3：CORS、缓存、Cookie / Session、协商和重定向归入 HTTP 文章；CSP 单独按安全策略解释。</li><li><code>05nginx代理配置/</code> 3：通用代理、HTTPS 和测试服务归入开发与部署；本地测试代码不复制。</li><li><code>MDN/</code> 1、<code>前端工程师应掌握的网络知识/</code> 3、<code>浏览器缓存/</code> 1：只吸收提纲和理解，不整篇搬运；PDF 留在源仓库。</li><li><code>demo/cache/</code> 3：缓存实验可按新文章在本地重做，旧服务代码不复制。</li></ul><h3 id="interviewmap-27" tabindex="-1">interviewMap（27） <a class="header-anchor" href="#interviewmap-27" aria-label="Permalink to &quot;interviewMap（27）&quot;">​</a></h3><ul><li><code>JS必知点/</code> 12：分为 JS 基础串联与异步控制两篇，覆盖 Generator、Promise、Proxy、async / await、call / apply / bind、数组 API、类型、原型、模块化、深浅拷贝、闭包、防抖节流。</li><li><code>Browser/</code> 5：进入浏览器机制串联，保留事件、存储、渲染与跨域的验证问题。</li><li><code>安全/</code> 2：进入 XSS、CSRF 与认证安全自测。</li><li><code>性能/</code> 5：进入前端性能诊断自测；test.html 留在源仓库。</li><li><code>框架通识/mvvm.md</code> 1：进入 MVVM、响应式与数据流自测。</li><li><code>readme.md</code>、<code>test.html</code> 2：目录说明和测试壳不复制；原文提到的上游归属没有在未核实前补造链接。</li></ul><h2 id="后续补充规则" tabindex="-1">后续补充规则 <a class="header-anchor" href="#后续补充规则" aria-label="Permalink to &quot;后续补充规则&quot;">​</a></h2><p>新增笔记先判断它属于概念原理、可运行实践还是学习自测；同一主题只保留一个可维护入口。实践记录应附代码位置、运行命令、环境和结果；尚未验证的方案标注为计划。发现旧资料中的版本、命令或安全边界与当前官方文档冲突时，以官方文档和可复现实验为准。</p><blockquote><p>源仓库：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7" target="_blank" rel="noreferrer">Fridolph/Fridolph</a>。</p></blockquote>',24)])])}const u=d(a,[["render",c]]);export{m as __pageData,u as default};
